package com.andye.warmod.antiair;import com.andye.warmod.icbm.IcbmFlightPlan;import com.andye.warmod.radar.*;import com.andye.warmod.warhead.WarheadPayloadType;import java.util.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.phys.Vec3;public final class AntiAirTargetSelector{private AntiAirTargetSelector(){}public static Optional<AntiAirTargetLock> acquire(ServerLevel level,Vec3 origin){long now=level.getGameTime();return RadarTrackingService.currentTelemetry(level,now).stream().filter(t->t.kind()==RadarTrackKind.ICBM&&t.phase()!=RadarTrackPhase.IMPACT&&t.snapshot().carrierPlan().isPresent()&&t.snapshot().strategicPayloadType().isPresent()).map(t->candidate(t,now)).filter(c->horizontal(origin,c.currentPosition())<=AntiAirConstants.ACQUISITION_CURRENT_RADIUS_BLOCKS&&horizontal(origin,c.predictedImpactPosition())<=AntiAirConstants.DEFENDED_IMPACT_RADIUS_BLOCKS).min(Comparator.comparingDouble((AntiAirTargetCandidate c)->horizontal(origin,c.currentPosition())).thenComparingLong(AntiAirTargetCandidate::estimatedImpactGameTime).thenComparingInt(c->c.payloadType()==WarheadPayloadType.NUCLEAR?0:1).thenComparing(c->c.rootTrackId().toString())).map(c->new AntiAirTargetLock(c.rootTrackId(),c.payloadType(),c.carrierPlan(),now,c.separationGameTime(),c.estimatedImpactGameTime()));}private static AntiAirTargetCandidate candidate(RadarTrackingService.RadarTrackTelemetry t,long now){var p=t.snapshot().carrierPlan().orElseThrow();WarheadPayloadType payload=t.snapshot().strategicPayloadType().orElseThrow();IcbmFlightPlan plan=new IcbmFlightPlan(t.trackId(),t.snapshot().ownerPlayerId(),p.launchPosition(),p.burnoutPosition(),p.separationPosition(),p.intendedTarget(),p.launchGameTime(),p.ignitionTicks(),p.boostTicks(),p.coastTicks(),p.visualSeed(),payload);return new AntiAirTargetCandidate(t.trackId(),payload,plan,t.phase(),t.currentPosition(),t.currentVelocity(),t.predictedImpactPosition(),now,plan.launchGameTime()+plan.separationTick(),plan.launchGameTime()+plan.separationTick());}public static double horizontal(Vec3 a,Vec3 b){return Math.hypot(a.x-b.x,a.z-b.z);}}